CREATE TRIGGER RefUNLOCOPortMapping_Version_Create
	ON RefUNLOCOPortMapping
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT RLM_PK, 'RLM'
	FROM inserted
GO
CREATE TRIGGER RefUNLOCOPortMapping_Version_Update
	ON RefUNLOCOPortMapping
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON RLM_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
CREATE TRIGGER RefUNLOCOPortMapping_DataChangeHistory
	ON RefUNLOCOPortMapping
	FOR INSERT, UPDATE, DELETE
	AS
	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT RLM_PK, 'RLM' FROM inserted
	UNION
	SELECT RLM_PK, 'RLM' FROM deleted

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO
CREATE TRIGGER RefUNLOCOPortMapping_DataProcessingResult_Delete
	ON RefUNLOCOPortMapping
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.RLM_PK
	END
